def rule(a: int, b: int, c: int) -> bool:
    def is_cube(n: int) -> bool:
        for i in range(-3, 4):
            if i * i * i == n:
                return True
        return False

    def is_even(n: int) -> bool:
        return n % 2 == 0

    cubes = [a, b, c]
    if len(cubes) != len(set(cubes)):
        return False

    even_count = 0
    for cube in cubes:
        if not is_cube(cube):
            return False
        root = round(cube ** (1/3))
        if is_even(root):
            even_count += 1
        if even_count > 1:
            return False

    return True

